KG42.register("rules-81d914e741f0c5b5f520d908",{"id":"27-multiple_microgrid_trading::v141-c-R012","paper":"27-multiple_microgrid_trading","record":{"rule_id":"v141-c-R012","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"Microgrids pay for energy purchases and transportation of purchased energy, and receive payment for energy sold. Scope: Economic interpretation of energy transactions among interconnected islanded microgrids. Inter-microgrid energy transactions may incur a tax charged by the distribution network operator. Scope: Optional transaction-tax component of inter-microgrid energy-transfer costs. Condition: When the transfer-cost model includes a tax charged by the distribution network operator for energy transactions.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade","settlement.payment"],"E":[{"edge_id":"v141-c-R012-E001","source":"execution.energy_trade","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R012-C001","v141-c-R012-C002"],"evidence_ids":["v141-b-g07-e007","v141-b-g23-e023"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Economic interpretation of energy transactions among interconnected islanded microgrids. | Optional transaction-tax component of inter-microgrid energy-transfer costs.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g07-e007","v141-b-g23-e023"]},"x":[{"variable_id":"v141-c-R012-x-Eji","symbol":"E_{j,i}","meaning":"Energy quantity bought by μG-i from μG-j in the local subproblem, used here as the settled purchase quantity in μG-i’s net-expenditure accounting; in Case 6 it is positive for j in S_* and zero otherwise.","kind":"operational","domain":"nonnegative real energy quantity, E_{j,i} ≥ 0 (MWh)","unit":"MWh","indices":["j","i"],"evidence_ids":["v141-b-g06-e006","v141-b-g15-e015","v141-b-g02-e022"]},{"variable_id":"v141-c-R012-x-eps","symbol":"\\varepsilon^{(s)}_i","meaning":"Energy sold by μG-i in the local subproblem, used here as the sold-energy quantity whose revenue enters μG-i’s net-expenditure accounting.","kind":"operational","domain":"nonnegative real energy quantity, \\varepsilon^{(s)}_i ≥ 0 (MWh)","unit":"MWh","indices":["i"],"evidence_ids":["v141-b-g15-e015","v141-b-g02-e022","v141-b-g23-e023"]}],"theta":[{"parameter_id":"v141-c-R012-theta-Ci","symbol":"C_i(\\cdot)","meaning":"Generation cost function of μG-i, mapping generated energy to cost; it appears as the production-cost term in net expenditure.","value":{"kind":"symbolic","number_value":null,"text_value":"symbolic cost function C_i(\\cdot); no single numeric value is fixed for this rule"},"unit":"USD","indices":["i"],"evidence_ids":["v141-b-g07-e007","v141-b-g02-e022"]},{"parameter_id":"v141-c-R012-theta-gamma","symbol":"\\gamma(\\cdot)","meaning":"Common transfer cost function for energy transferred on a μG link; the source states it may model a distribution-network-operator tax and congestion soft constraints.","value":{"kind":"symbolic","number_value":null,"text_value":"symbolic transfer-cost function \\gamma(\\cdot); no single numeric value is fixed for this rule"},"unit":"USD","indices":[],"evidence_ids":["v141-b-g07-e007","v141-b-g02-e022"]},{"parameter_id":"v141-c-R012-theta-Ec","symbol":"E^{(c)}_i","meaning":"Local energy consumption/load of μG-i, treated as a fixed input in the payment accounting; the source case analysis assumes positive load and also discusses a zero-load extension.","value":{"kind":"symbolic","number_value":null,"text_value":"symbolic local consumption/load parameter E^{(c)}_i"},"unit":"MWh","indices":["i"],"evidence_ids":["v141-b-g04-e004","v141-b-g02-e022","v141-b-g37-e037"]},{"parameter_id":"v141-c-R012-theta-lambda-i","symbol":"\\lambda^*_i","meaning":"Equilibrium per-unit selling price requested by μG-i, interpreted as the price per energy unit for energy sold and used to value μG-i’s sales revenue in the settlement accounting.","value":{"kind":"symbolic","number_value":null,"text_value":"equilibrium price \\lambda^*_i; no numeric value is fixed in this rule"},"unit":"USD/MWh","indices":["i"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e023","v141-b-g23-e023"]},{"parameter_id":"v141-c-R012-theta-lambda-j","symbol":"\\lambda^*_j","meaning":"Equilibrium per-unit buying price paid by μG-i to μG-j for purchased energy j→i in the settlement accounting.","value":{"kind":"symbolic","number_value":null,"text_value":"equilibrium price \\lambda^*_j; no numeric value is fixed in this rule"},"unit":"USD/MWh","indices":["j"],"evidence_ids":["v141-b-g02-e019","v141-b-g02-e022","v141-b-g02-e023"]}],"phi":[{"constraint_id":"v141-c-R012-C001","kind":"procedural","role":"core","statement":"Microgrids pay for energy purchases and transportation of purchased energy, and receive payment for energy sold. Scope: Economic interpretation of energy transactions among interconnected islanded microgrids.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g23-e023"]},{"constraint_id":"v141-c-R012-C002","kind":"procedural","role":"core","statement":"Inter-microgrid energy transactions may incur a tax charged by the distribution network operator. Scope: Optional transaction-tax component of inter-microgrid energy-transfer costs. Condition: When the transfer-cost model includes a tax charged by the distribution network operator for energy transactions.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g07-e007"]},{"constraint_id":"v141-c-R012-C003","kind":"mathematical","role":"core","statement":"At the equilibrium price vector, μG-i’s net expenditure (payment outflow minus income) equals the generation cost of its net energy output plus the transfer costs and purchase payments for energy bought from the suppliers in S_*, minus the revenue from the energy it sells, as given by the source’s Case 6 net-expenditure formula.","expression":"C^{(l)}_i(\\lambda^*) = C_i\\left(E^{(c)}_i + \\varepsilon^{(s)}_i - \\sum_{j\\in S_*} E_{j,i}\\right) + \\sum_{j\\in S_*} \\gamma(E_{j,i}) + \\sum_{j\\in S_*} \\lambda^*_j E_{j,i} - \\lambda^*_i \\varepsilon^{(s)}_i","formalization_origin":"source","template_id":null,"members":["execution.energy_trade","settlement.payment"],"variable_refs":["v141-c-R012-x-Eji","v141-c-R012-x-eps"],"parameter_refs":["v141-c-R012-theta-Ci","v141-c-R012-theta-gamma","v141-c-R012-theta-Ec","v141-c-R012-theta-lambda-i","v141-c-R012-theta-lambda-j"],"evidence_ids":["v141-b-g02-e022","v141-b-g23-e023"]}],"pi":[{"evidence_id":"v141-b-g07-e007","location":{"location_id":"src-f5dd785b87-p02-c2r3__v141-a-M01-pricing","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"0 MWh for all i, j = 1, . . . , M. ach Next, let Ci(E(g)i ) and γ(Ei,j) be the costs of producing E(","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Next, let C_i(E_i^{(g)}) and γ(E_{i,j}) be the costs of producing E_i^{(g)} units of energy at μG-i and transferring E_{i,j} units of energy on the μG-i−μG-j link, respectively. This transferring cost function may model several factors. For example, the distribution network operator, as the enabler of the energy transfer between the μGs, may charge a tax for energy transactions. In addition, this transfer cost function may also account for line congestions by introducing soft constraints on the maximum capacity of the line (see Section II-A for further information). Although the solution in the following may be extended to the case where different links have different transfer cost functions, we assume that γ(·) is common among all the links in order to avoid further complexity. As it will be clearer later, our approach is quite general and only requires that all cost functions (both production and transport) satisfy some mild convexity constraints, which are summarized in Section II-A."},{"evidence_id":"v141-b-g23-e023","location":{"location_id":"src-f5dd785b87-p04-c1r4__v141-a-M01-pricing","page":4,"printed_page":null,"section":"III-A. Decentralizing the Problem","anchor_text":", g ining interpretation: Each Lagrange multiplier λi may be under- costood as the price per energy ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"Each Lagrange multiplier λ_i may be understood as the price per energy unit requested by μG-i to sell energy to its neighbors. Then, Lagrangian function (7) can be seen as the “net expenditure” (the opposite of the net income) for μG-i, i.e., each μG pays for producing energy, for buying energy, and for transporting the energy it buys. Conversely, the μG is paid for the energy it sells. By solving problem (6), μG-i is thus maximizing its benefit for some given selling (λ_i[k]) and buying (λ_j[k], j≠i) prices per energy unit."},{"evidence_id":"v141-b-g02-e019","location":{"location_id":"src-f5dd785b87-p05-c2r4__v141-a-M01-pricing","page":5,"printed_page":null,"section":"III-C. Interpretation and Summary","anchor_text":"It is interesting to note that the optimal solution provided in the previous section has a straightf","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Recall that, at \\mu G-i, the Lagrange mul-tipliers can be interpreted as the unitary selling price (\\lambda_i) and the unitary buying prices from the other \\mu Gs, that is \\{\\lambda_j\\}, with j \\neq i. Moreover, derivatives C'_i(\\cdot) and \\gamma'(\\cdot) are the marginal generation cost and the marginal transportation cost, respectively, that are the linear variation on the cost due to an infinitesimal variation of the generated or transported energy, respectively."},{"evidence_id":"v141-b-g02-e022","location":{"location_id":"src-f5dd785b87-p06-c1r2__v141-a-M01-pricing","page":6,"printed_page":null,"section":"III-C. Interpretation and Summary","anchor_text":"diture Ci (λ ) in (7), where λ stands for the optimal point of (5). For the sake of brevity, we prov","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"In Case 6, the net expenditure reads\nC^{(l)}_i(\\lambda^*) = C_i\\left(E^{(c)}_i + \\varepsilon^{(s)}_i - \\sum_{j \\in S_*} E_{j,i}\\right) + \\sum_{j \\in S_*} \\gamma(E_{j,i}) + \\sum_{j \\in S_*} \\lambda^*_j E_{j,i} - \\lambda^*_i \\varepsilon^{(s)}_i\nwhere (\\varepsilon^{(s)}_i, \\{E_{j,i}\\}) = (\\varepsilon^{(s)}_i(\\lambda^*), \\{E_{j,i}(\\lambda^*)\\}) is now the min-imum point of (6) for \\lambda = \\lambda^*."},{"evidence_id":"v141-b-g02-e023","location":{"location_id":"src-f5dd785b87-p06-c1r2__v141-a-M01-pricing","page":6,"printed_page":null,"section":"III-C. Interpretation and Summary","anchor_text":"diture Ci (λ ) in (7), where λ stands for the optimal point of (5). For the sake of brevity, we prov","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Next, by means of the results of Case 6, one has \\lambda^*_i = C'_i(E^{(g)}_i) and \\lambda^*_j = \\lambda^*_i - \\gamma'(E_{j,i}) for all j \\in S_*."},{"evidence_id":"v141-b-g04-e004","location":{"location_id":"src-f5dd785b87-p02-c2r1__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"IEEE TRANSACTIONS ON INDUSTRIAL ELECTRONICS, VOL. 62, NO. 4, APRIL 2015 we from an economical point ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Consider a system composed of M interconnected microgrids (μGs) operating in islanded mode. During each scheduling interval, each microgrid μG-i generates E_i^{(g)} units of energy and consumes E_i^{(c)} units of energy. Moreover, μG-i may be allowed to sell energy E_{i,j} to μG-j, j≠i, and to buy energy E_{k,i} from μG-k, k≠i. Then, the energy equilibrium within the μG requires E_i^{(g)} + e_i^T A^T E_i^{(b)} = E_i^{(c)} + e_i^T A E_i^{(s)} (1)"},{"evidence_id":"v141-b-g06-e006","location":{"location_id":"src-f5dd785b87-p02-c2r2__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. System Model","anchor_text":"to sell energy Ei,j to μG j, j̸ i, and to buy energy Ek,i fromrgy μG-k, k̸=i. Then, the energy equil","equation_id":"(2)","figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"where the two M-dimensional column vectors, i.e., E_i^{(b)} = [E_{1,i} ... E_{M,i}]^T, E_i^{(s)} = [E_{i,1} ... E_{i,M}]^T (2) gather all the energy quantities bought and sold, respectively, by μG-i. In addition, we have introduced adjacency matrix A = [a_{i,j}]_{M×M}, where element a_{i,j} is equal to 1 if there exists a connection from μG-i to μG-j and 0 otherwise. Note that, generally, A may be nonsymmetric, meaning that at least two μGs are allowed to exchange energy in one direction only. By convention, we fix a_{i,i}=0. Moreover, a_{i,j}=0 ⇒ E_{i,j}=0 MWh for all i,j=1,...,M."},{"evidence_id":"v141-b-g15-e015","location":{"location_id":"src-f5dd785b87-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":"III-A. Decentralizing the Problem","anchor_text":"i i i i i at {ε(s)i },{Ei,j} i=1 + eTi AT γ(E(b)i ) i=1 s.t. Ei,j ≥0 ∀i,j ks ey E(c)i + ε(s)i −eTi A","equation_id":"(4)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"C^* = min_{ {ε_i^{(s)}},{E_{i,j}} } ∑_{i=1}^M C_i(E_i^{(c)} + ε_i^{(s)} - e_i^T A^T E_i^{(b)}) + ∑_{i=1}^M e_i^T A^T γ(E_i^{(b)}) s.t. E_{i,j} ≥ 0 ∀i,j, E_i^{(c)} + ε_i^{(s)} - e_i^T A^T E_i^{(b)} ≥ 0 ∀i, ε_i^{(s)} = e_i^T A E_i^{(s)} ∀i. (4) The idea is that, for each μG, we first use the new variable ε_i^{(s)} to represent the energy sold by μG-i and only later force it to be equal to all the energy bought by other μGs from μG-i, i.e., ε_i^{(s)}=e_i^T A E_i^{(s)}, which is the coupling constraint."},{"evidence_id":"v141-b-g37-e037","location":{"location_id":"src-f5dd785b87-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":"III-C. Interpretation and Summary","anchor_text":"assumptions are necessary for each given case. Furthermore, one can also derive the exact values of ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"As a final remark, note that we are assuming a positive load at the μGs, i.e., E_i^{(c)} > 0 ∀i. The case where E_i^{(c)} = 0 may be analogously handled and brings similar results. More specifically, Cases 4, 5, and 6 directly extend because of continuity. Conversely, Cases 2 and 3 disappear and expand the domain of Case 1 to λ_i ≤ C_i'(0) and λ_min ≥ λ_i - γ'(0)."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g23-e023","quote":"each μG pays for producing energy, for buying energy, and for transporting the energy it buys. Conversely, the μG is paid for the energy it sells."}],[{"evidence_id":"v141-b-g07-e007","quote":"For example, the distribution network operator, as the enabler of the energy transfer between the μGs, may charge a tax for energy transactions."}]],"C2_formalization":{"graph_sha256":"71f8d0939b67c897767ab152cef7eceb730f041f38fd432e4793a9dbc22099af","applicability":"formalized","reason":"The source supplies an explicit algebraic net-expenditure/payment identity for μG-i in Case 6 at equilibrium prices (v141-b-g02-e022), plus the economic interpretation that μGs pay for production, purchases and transport and are paid for sales (v141-b-g23-e023). C001 and C002 are retained as qualitative/procedural statements; the optional distribution-network-operator tax has no quantitative expression in the supplied source. B evidence remains unreviewed and no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R012-x-Eji","node_ids":["execution.energy_trade","settlement.payment"],"edge_ids":["v141-c-R012-E001"],"rationale":"E_{j,i} is a directed inter-microgrid energy-trade quantity; the frozen edge execution.energy_trade→settlement.payment represents the relation by which purchased energy gives rise to a payment obligation. The source net-expenditure formula uses E_{j,i} in both the transfer-cost and purchase-payment sums."},{"object_id":"v141-c-R012-x-eps","node_ids":["execution.energy_trade","settlement.payment"],"edge_ids":["v141-c-R012-E001"],"rationale":"\\varepsilon^{(s)}_i is the energy sold by μG-i; the frozen edge represents the settlement relation linking sold energy to the payment received, and the source formula subtracts λ^*_i \\varepsilon^{(s)}_i from net expenditure."},{"object_id":"v141-c-R012-theta-Ci","node_ids":["settlement.payment"],"edge_ids":["v141-c-R012-E001"],"rationale":"C_i(·) is the generation-cost component of μG-i’s net expenditure; it is bound to the payment node because the source accounting treats production cost as part of the payment outflow, with trade quantities determining net generation through the frozen trade→payment relation."},{"object_id":"v141-c-R012-theta-gamma","node_ids":["execution.energy_trade","settlement.payment"],"edge_ids":["v141-c-R012-E001"],"rationale":"\\gamma(·) is the transfer-cost function for traded energy; it is bound to both the energy-trade node and the payment node because the source adds transfer costs for purchased quantities to μG-i’s net expenditure."},{"object_id":"v141-c-R012-theta-Ec","node_ids":["execution.energy_trade","settlement.payment"],"edge_ids":["v141-c-R012-E001"],"rationale":"E^{(c)}_i is the fixed local load entering the net-generation argument of C_i; it shapes the quantity of energy purchased or sold and therefore the settlement payment under the frozen trade→payment edge."},{"object_id":"v141-c-R012-theta-lambda-i","node_ids":["settlement.payment"],"edge_ids":["v141-c-R012-E001"],"rationale":"\\lambda^*_i is the equilibrium selling price used to value μG-i’s sales revenue in the net-expenditure formula; it is bound to settlement.payment as the price applied to the trade quantity."},{"object_id":"v141-c-R012-theta-lambda-j","node_ids":["settlement.payment"],"edge_ids":["v141-c-R012-E001"],"rationale":"\\lambda^*_j is the equilibrium price μG-i pays per unit purchased from μG-j; it is bound to settlement.payment because it multiplies purchased quantities in the payment term."},{"object_id":"v141-c-R012-C003","node_ids":["execution.energy_trade","settlement.payment"],"edge_ids":["v141-c-R012-E001"],"rationale":"The source formula expresses the net expenditure resulting from traded energy: production cost of net output, transfer costs and purchase payments for bought energy, and revenue from sold energy. The frozen edge execution.energy_trade→settlement.payment directly represents this payment relation."}],"revision_requests":[]}},"quarantined_references":[]}});
